class _PamAuthenticatorProxy:
    """Proxy wrapper that converts authenticate() return values to boolean."""

    def __init__(self, authenticator):
        self._authenticator = authenticator

    def __getattr__(self, name):
        # Delegate all attribute access to the wrapped authenticator
        return getattr(self._authenticator, name)

    def authenticate(self, *args, **kwargs):
        # Convert the return value to boolean
        result = self._authenticator.authenticate(*args, **kwargs)
        return result == 0  # PAM_SUCCESS = 0


